export type Item = { type: string };
export type Step = { items: Item[] };
export type Scenario = { steps: Step[] };
export type Result = { premium: number };
export type ScenarioOutcome = { results: Result[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

const FIRST_INSURANCE_SURCHARGE = 1.1;
const PROCESSING_FEE = 5;

const roundUpToWholeGold = (amount: number): number =>
  Math.ceil(Number(amount.toFixed(6)));

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const basePremium = BASE_PREMIUMS[scenario.steps[0].items[0].type];
  const premium =
    roundUpToWholeGold(basePremium * FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
  return { results: [{ premium }] };
};
